def all_orfs(s,minaa=90):
    res=[]
    for f in range(3):
        # consider starts ATG, GTG, TTG
        i=f; start=None; sc=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if start is None:
                if cod in ("ATG","GTG","TTG"):
                    start=i; sc=cod
            else:
                if cod in stop:
                    if (i-start)//3>=minaa: res.append((f,start,i,sc))
                    start=None
            i+=3
    return res

